    if (v) bits.push(v.state === "overdue" ? '<span class="w-st escalate">' + esc(v.text) + "</span>" : esc(v.text) + (v.dueAt ? " " + when(v.dueAt) : ""));
    return bits.length ? '<div class="w-dt-times">' + bits.join(" &middot; ") + "</div>" : "";
