    if ((!clinicianId && !resourceId) || (clinicianId && resourceId)) { st.scheduling.err = wT("ward.name-exactly-one-clinician-or-one", "Name exactly one clinician or one resource."); paint(); return; }
    if (!from || !to || !reason) { st.scheduling.err = wT("ward.a-start-an-end-and-a", "A start, an end and a reason are all required."); paint(); return; }
    st.scheduling.err = ""; st.busy = true; paint();
