    apiPost("/ward/cancel-blackout", { orgId: st.orgId, blackoutId: blackoutId })
      .then(function (r) { st.busy = false; if (r && r.ok) loadScheduling(); else { st.scheduling.err = (r && r.detail) || wT("ward.could-not-unblock-that-period", "Could not unblock that period."); paint(); } })
      .catch(function () { st.busy = false; st.scheduling.err = wT("ward.could-not-reach-the-server2", "Could not reach the server."); paint(); });
