    var diluent = val("wMoDiluentVal"), duration = val("wMoInfDuration"), instr = checkedInstructions("wMoInstr");
    if (!drug || !value || !unit) return { err: wT("ward.drug-dose-and-unit-are-required", "Drug, dose and unit are required.") };
