  function loadMedRec() {
    var s = st.sel; if (!s) return Promise.resolve();
    st.busy = true; paint();
    return apiGet("/ward/med-reconciliation?orgId=" + encodeURIComponent(st.orgId) + "&encounterId=" + encodeURIComponent(s.encounterId))
      .then(function (r) {
        st.busy = false;
        if (r && r.ok) st.medRec = r;
        else { st.medRec = null; st.err = wT("ward.could-not-load-the-medicines-history", "Could not load the medicines history. Do not read this as none recorded."); }
        paint();
      })
      .catch(function () { st.busy = false; st.medRec = null; st.err = wT("ward.could-not-load-the-medicines-history", "Could not load the medicines history. Do not read this as none recorded."); paint(); });
  }
  function medRecStart() {
    var s = st.sel; if (!s) return;
    var text = val("wMrMeds");
    if (!text) { st.err = wT("ward.write-down-what-the-patient-is", "Write down what the patient is taking."); paint(); return; }
    /* One medicine a line, exactly as typed. Nothing here parses a dose out of the words: a parser
     * that guessed "500mg" from a line and got it wrong would put a made-up dose on the record. */
    var medicines = text.split("\n").map(function (l) { return l.trim(); }).filter(Boolean)
      .map(function (l) { return { drug: l }; });
    if (!medicines.length) { st.err = wT("ward.write-down-what-the-patient-is", "Write down what the patient is taking."); paint(); return; }
    st.busy = true; paint();
    apiPost("/ward/med-history", {
      orgId: st.orgId, encounterId: s.encounterId, stage: val("wMrStage") || "admission",
      source: val("wMrSource") || undefined, medicines: medicines,
    })
      .then(function (r) {
        if (settle(r, r && r.ok ? wT("ward.recorded-each-medicine-still-needs-a", "Recorded. Each medicine still needs a decision.") : null)) {
          var el = document.getElementById("wMrMeds"); if (el) el.value = "";
          loadMedRec();
        } else paint();
      })
      .catch(function () { st.busy = false; st.err = wT("ward.could-not-record-that", "Could not record that."); paint(); });
  }
  function medRecDecide(arg) {
    var s = st.sel; if (!s) return;
    var parts = String(arg || "").split("~");
    var stage = parts[0], key = parts[1], decision = parts[2];
    if (!stage || !key || !decision) return;
    /* The module requires a reason for the decisions that change what the patient takes; asking for
     * one on every decision is simpler than encoding that rule twice, and the server is still the
     * one that enforces it (its refusal is shown in the dialog). */
    askReason(wTH("ward.why-required-for-stopping-or-changing", "Why? (required for stopping or changing a medicine)"), "", null, function (reason) {
      st.busy = true; paint();
      return apiPost("/ward/med-decide", {
        orgId: st.orgId, encounterId: s.encounterId, stage: stage, key: key,
        decision: decision, reason: reason || undefined,
      })
        .then(function (r) { if (settle(r, r && r.ok ? wT("ward.decided", "Decided.") : null)) loadMedRec(); else paint(); })
        .catch(function () { st.busy = false; st.err = wT("ward.could-not-record-that-decision", "Could not record that decision."); paint(); });
    }, { icon: "medication" });
  }

