        var boxes = document.querySelectorAll('[data-w-formmulti="' + fd.key + '"]'), picked = [];
        for (var i = 0; i < boxes.length; i++) if (boxes[i].checked) picked.push(boxes[i].value);
        if (picked.length) a[fd.key] = picked; return;
