              '<ul class="w-icd">' + rows.map(function (c, i) {
                return '<li><button class="w-icd-p" data-w-act="icdpick:' + i + '"><b>' + esc(c.code) + "</b><span>" + esc(c.title) + "</span><small>" + esc(c.system || "") + "</small></button></li>";
              }).join("") + "</ul>"
